children.text:
@font-face {
    font-family: 'Liberation Sans';
    src: url('../font/LiberationSans-Regular.ttf') format('truetype');
    font-weight: normal;
    font-style: normal;
}
@font-face {
    font-family: 'Liberation Sans';
    src: url('../font/LiberationSans-Bold.ttf') format('truetype');
    font-weight: bold;
    font-style: normal;
}
@font-face {
    font-family: 'Liberation Serif';
    src: url('../font/LiberationSerif-Regular.ttf') format('truetype');
    font-weight: normal;
    font-style: normal;
}
@font-face {
    font-family: 'Liberation Mono';
    src: url('../font/LiberationMono-Regular.ttf') format('truetype');
    font-weight: normal;
    font-style: normal;
}
@font-face {
    font-family: 'Open Sans';
    src: url('../font/OpenSans-Regular.ttf') format('truetype');
    font-weight: normal;
    font-style: normal;
}

body {
    font-family: 'Liberation Sans', Arial, sans-serif;
    font-size: 16px;
    line-height: 1.6;
    margin: 20px;
    background-color: white;
    color: black;
}

.document-container {
    max-width: 700px;
    padding: 30px;
    border: 1px solid #ccc;
}

.header {
    font-family: 'Open Sans', sans-serif;
    font-size: 28px;
    color: #2c3e50;
    margin-bottom: 20px;
    text-align: center;
}

.article-content {
    font-family: 'Liberation Serif', 'Times New Roman', serif;
    font-size: 16px;
    text-align: justify;
    margin-bottom: 20px;
}

.code-section {
    font-family: 'Liberation Mono', 'Courier New', monospace;
    font-size: 14px;
    background-color: #f5f5f5;
    padding: 15px;
    border-left: 4px solid #007acc;
    margin: 20px 0;
    white-space: pre-wrap;
}

.sidebar-note {
    font-family: 'Liberation Sans', Arial, sans-serif;
    font-size: 14px;
    background-color: #fff3cd;
    padding: 15px;
    border: 1px solid #ffeaa7;
    border-radius: 5px;
    margin: 15px 0;
}

.tech-specs {
    font-family: 'Liberation Mono', monospace;
    font-size: 12px;
    background-color: #e9ecef;
    padding: 10px;
    border: 1px solid #ced4da;
}
